// Функция setup выполняется один раз при нажатии кнопки Reset или подаче питания
void setup() {
  // Инициализируем цифровой пин 13 как выход (OUTPUT)
  pinMode(13, OUTPUT);
}

// Функция loop выполняется по кругу бесконечно
void loop() {
  digitalWrite(13, HIGH); // Подаем высокий уровень (5В), светодиод загорается
  delay(1000);            // Ждем 1000 миллисекунд = 1 секунду

  digitalWrite(13, LOW);  // Подаем низкий уровень (0В), светодиод гаснет
  delay(1000);            // Снова ждем 1 секунду
}
